corrected_code:
router.post('/payments/refund', async (req, res) => {
  const { paymentId } = req.body;
  const payment = await PaymentModel.findOne({ _id: paymentId, accountId: req.user.accountId });
  if (!payment) return res.status(404).send('Payment not found');
  if (payment.status !== 'completed') return res.status(400).send('Invalid status');
  await processRefund(payment);
  res.json({ success: true });
});
